insert into public.kakao_weather_regions(region_key,label,nx,ny,forecast_code,enabled,verified_at) values('web:1100000000','Synthetic region',60,127,'1100000000',true,now());
insert into public.kakao_multi_connections(owner_id,account_id,encrypted_tokens,status,generation,talk_message_granted) select id,'fake-account','fake-cipher','connected',1,true from public.profiles where login_id='qa_staff';
insert into public.kakao_multi_preferences(owner_id,weather_region_key,enabled) select id,'web:1100000000',true from public.profiles where login_id='qa_staff';
update public.kakao_multi_controls set enabled=true,monthly_message_budget=10,monthly_function_budget=30,cost_verified_until=now()+interval '1 day',tick_endpoint='https://fake.supabase.co/functions/v1/hwarang-kakao/tick' where singleton;
create temporary table before_state as select (select count(*) from public.kakao_multi_batches) batches,(select count(*) from public.kakao_multi_jobs) jobs,(select jsonb_agg(to_jsonb(s)) from public.kakao_multi_cron_slots s) slots,(select jsonb_agg(to_jsonb(p)) from public.kakao_multi_preferences p) prefs;
insert into public.kakao_multi_test_requests(owner_id,ticket_hash,expires_at) select id,repeat('a',64),now()+interval '3 minutes' from public.profiles where login_id='qa_staff';
do $$declare r jsonb;begin
 if public.kakao_test_claim(repeat('b',64)) is not null then raise exception 'Wrong ticket accepted';end if;
 r:=public.kakao_test_claim(repeat('a',64));
 if r is null or r->>'claim_token' is null then raise exception 'No claim';end if;
 if public.kakao_test_claim(repeat('a',64)) is not null then raise exception 'Reclaimed';end if;
 if not public.kakao_test_validate((r->>'id')::uuid,(r->>'claim_token')::uuid) then raise exception 'Valid claim denied';end if;
 if public.kakao_test_validate((r->>'id')::uuid,gen_random_uuid()) then raise exception 'Wrong claim allowed';end if;
 if not public.kakao_test_complete((r->>'id')::uuid,(r->>'claim_token')::uuid,'uncertain') then raise exception 'Completion failed';end if;
 if public.kakao_test_complete((r->>'id')::uuid,(r->>'claim_token')::uuid,'accepted') or public.kakao_test_claim(repeat('a',64)) is not null then raise exception 'Uncertain retried';end if;
 if exists(select 1 from before_state b where b.batches<>(select count(*) from public.kakao_multi_batches) or b.jobs<>(select count(*) from public.kakao_multi_jobs) or b.slots is distinct from (select jsonb_agg(to_jsonb(s)) from public.kakao_multi_cron_slots s) or b.prefs is distinct from (select jsonb_agg(to_jsonb(p)) from public.kakao_multi_preferences p)) then raise exception 'Normal state mutated';end if;
 if has_function_privilege('anon','public.kakao_test_claim(text)','execute') or has_function_privilege('authenticated','public.kakao_test_complete(uuid,uuid,text)','execute') or has_table_privilege('authenticated','public.kakao_multi_test_requests','select') then raise exception 'ACL leak';end if;
 begin insert into public.kakao_multi_test_requests(owner_id,ticket_hash,expires_at) select owner_id,repeat('c',64),now()+interval '3 minutes' from public.kakao_multi_test_requests;raise exception 'Duplicate owner accepted';exception when unique_violation then null;end;
end $$;
select 'PASS: wrong/repeated tickets, claim token binding, terminal uncertainty, owner uniqueness, ACL, normal batch/job/prefs/cron unchanged' as result;
